// Runtime for the mechanically-ported Code.gs functions in
// legacy/codegs.js (generated by tools/legacy-port/generate.js — see
// that file's header for how the port works and why).
//
// Everything Code.gs did against the outside world went through a very
// small set of chokepoints: firebaseDbRequest_ (RTDB REST), the
// firestore*_ CRUD/query helpers (Firestore REST), firebaseAuthRequest_
// (Identity Toolkit REST), requireUser_, LockService and Utilities.
// This file re-implements exactly those, on the Admin SDK, with the
// REST semantics the original code was written against — so the
// ported business logic itself can stay verbatim.
//
// The "idToken" every original function takes as its first argument is,
// in the port, a small context object ({ request }) created per
// callable invocation — see run() below. Original code only ever passed
// it through to these primitives (and requireUser_), so it keeps its
// name and position unchanged.
const { AsyncLocalStorage } = require('async_hooks');
const { randomUUID } = require('crypto');
const { admin, rtdb, firestore } = require('../firebaseAdmin');
const { FieldPath, Timestamp } = require('firebase-admin/firestore');
const { requireUser } = require('../auth');
const { acquireGlobalLock, releaseGlobalLock } = require('../lock');

const als = new AsyncLocalStorage();

// Runs one callable invocation with its own context — the value every
// ported function receives as "idToken", and the per-request state the
// LockService shim needs.
function run(request, fn) {
  const ctx = { request, lockDepth: 0 };
  return als.run(ctx, () => fn(ctx));
}

// REST drops undefined object keys (JSON.stringify) and turns NaN into
// null; the Admin SDK instead throws on undefined. A JSON round trip
// reproduces the REST behavior exactly.
function jsonClean(value) {
  if (value === undefined) return null;
  return JSON.parse(JSON.stringify(value));
}

// ---------- RTDB: firebaseDbRequest_ ----------
async function firebaseDbRequest_(path, method, payload, idToken) {
  const cleanPath = String(path).replace(/^\/+|\/+$/g, '');
  const ref = cleanPath ? rtdb.ref(cleanPath) : rtdb.ref();
  const m = String(method || 'get').toLowerCase();
  if (m === 'get') {
    return (await ref.get()).val();
  }
  if (m === 'put') {
    const data = jsonClean(payload);
    await ref.set(data);
    return data;
  }
  if (m === 'patch') {
    const data = jsonClean(payload) || {};
    if (Object.keys(data).length) await ref.update(data);
    return data;
  }
  if (m === 'post') {
    const child = ref.push();
    await child.set(jsonClean(payload));
    return { name: child.key };
  }
  if (m === 'delete') {
    await ref.remove();
    return null;
  }
  throw new Error('Firebase database request failed.');
}

// ---------- Firestore: the firestore*_ public surface ----------
// Matches toFirestoreFields_/toFirestoreValue_: undefined object keys
// are omitted, undefined array elements become null.
function toFs(value) {
  if (value === null || value === undefined) return null;
  if (Array.isArray(value)) return value.map(v => (v === undefined ? null : toFs(v)));
  if (typeof value === 'object') {
    const out = {};
    Object.keys(value).forEach(k => { if (value[k] !== undefined) out[k] = toFs(value[k]); });
    return out;
  }
  return value;
}
// Timestamps (never written by this codebase, but possible) come back
// as ISO strings, as fromFirestoreValue_ returned them.
function fromFs(value) {
  if (value === null || value === undefined) return value === undefined ? null : value;
  if (value instanceof Timestamp) return value.toDate().toISOString();
  if (Array.isArray(value)) return value.map(fromFs);
  if (typeof value === 'object') {
    const out = {};
    Object.keys(value).forEach(k => { out[k] = fromFs(value[k]); });
    return out;
  }
  return value;
}
function docToObj(snap) {
  if (!snap.exists) return null;
  const obj = fromFs(snap.data());
  obj._id = snap.id;
  return obj;
}

async function firestoreGet_(collection, docId) {
  return docToObj(await firestore.collection(collection).doc(String(docId)).get());
}
// Full replace, creating if missing ('put' semantics).
async function firestoreSet_(collection, docId, data) {
  const ref = firestore.collection(collection).doc(String(docId));
  await ref.set(toFs(data || {}));
  return docToObj(await ref.get());
}
// Top-level field merge with an update mask — replaces each named
// top-level field wholesale and creates the document if it's missing,
// exactly like the REST PATCH + updateMask the original built.
async function firestoreUpdate_(collection, docId, data) {
  const fieldNames = Object.keys(data || {});
  if (!fieldNames.length) return firestoreGet_(collection, docId);
  const ref = firestore.collection(collection).doc(String(docId));
  await ref.set(toFs(data), { mergeFields: fieldNames.map(f => new FieldPath(f)) });
  return docToObj(await ref.get());
}
async function firestoreAdd_(collection, data) {
  const ref = await firestore.collection(collection).add(toFs(data || {}));
  return docToObj(await ref.get());
}
async function firestoreDelete_(collection, docId) {
  await firestore.collection(collection).doc(String(docId)).delete();
}
const OPS = {
  EQUAL: '==', NOT_EQUAL: '!=', LESS_THAN: '<', LESS_THAN_OR_EQUAL: '<=',
  GREATER_THAN: '>', GREATER_THAN_OR_EQUAL: '>=', ARRAY_CONTAINS: 'array-contains',
  IN: 'in', NOT_IN: 'not-in', ARRAY_CONTAINS_ANY: 'array-contains-any'
};
function applyWhere(q, where) {
  (where || []).forEach(t => {
    const op = OPS[t[1]];
    if (!op) throw new Error('Unsupported Firestore operator: ' + t[1]);
    q = q.where(new FieldPath(...String(t[0]).split('.')), op, toFs(t[2]));
  });
  return q;
}
async function firestoreQuery_(collection, where, orderBy, limit) {
  let q = applyWhere(firestore.collection(collection), where);
  (orderBy || []).forEach(pair => { q = q.orderBy(pair[0], pair[1] === 'DESCENDING' ? 'desc' : 'asc'); });
  if (limit) q = q.limit(limit);
  const snap = await q.get();
  return snap.docs.map(docToObj);
}
async function firestoreCount_(collection, where) {
  const snap = await applyWhere(firestore.collection(collection), where).count().get();
  return Number(snap.data().count || 0);
}

// ---------- Auth ----------
async function requireUser_(idToken) {
  return requireUser(idToken && idToken.request ? idToken.request : { auth: null });
}
// Only 'accounts:signUp' (saveFirebaseUser's create path) reaches this
// in the port; requireUser_'s 'accounts:lookup' is replaced above by the
// callable platform's own pre-verified auth. Same error text as the
// REST API would surface for the common case.
async function firebaseAuthRequest_(endpoint, payload) {
  if (endpoint === 'accounts:signUp') {
    try {
      const u = await admin.auth().createUser({ email: payload.email, password: payload.password });
      return { localId: u.uid, email: u.email };
    } catch (err) {
      if (err && err.code === 'auth/email-already-exists') throw new Error('EMAIL_EXISTS');
      throw new Error((err && err.message) || 'Firebase Authentication request failed.');
    }
  }
  throw new Error('Unsupported auth endpoint in port: ' + endpoint);
}

// ---------- LockService ----------
// The GAS script lock is the SAME global lock the already-ported
// modules take (lock.js), so ported and legacy-ported commits still
// serialize against each other. Re-entrant per request, like a GAS
// script lock within one execution.
const LockService = {
  getScriptLock() {
    return {
      async waitLock() {
        const ctx = als.getStore();
        if (ctx && ctx.lockDepth > 0) { ctx.lockDepth++; return; }
        await acquireGlobalLock(ctx && ctx.request && ctx.request.auth ? ctx.request.auth.uid : 'legacy');
        if (ctx) ctx.lockDepth = 1;
      },
      async tryLock() {
        try { await this.waitLock(); return true; } catch (e) { return false; }
      },
      async releaseLock() {
        const ctx = als.getStore();
        if (ctx) {
          if (ctx.lockDepth <= 0) return;
          ctx.lockDepth--;
          if (ctx.lockDepth > 0) return;
        }
        await releaseGlobalLock();
      },
      hasLock() { const ctx = als.getStore(); return Boolean(ctx && ctx.lockDepth > 0); }
    };
  }
};

const Utilities = {
  getUuid: () => randomUUID()
};

// Sequential stand-ins for array callbacks that became async: the
// original ran them strictly in order (synchronous GAS), so these do too
// — never Promise.all, which would interleave writes.
const seq = {
  async forEach(arr, fn) { const a = Array.from(arr || []); for (let i = 0; i < a.length; i++) await fn(a[i], i, a); },
  async map(arr, fn) { const a = Array.from(arr || []); const out = []; for (let i = 0; i < a.length; i++) out.push(await fn(a[i], i, a)); return out; },
  async filter(arr, fn) { const a = Array.from(arr || []); const out = []; for (let i = 0; i < a.length; i++) if (await fn(a[i], i, a)) out.push(a[i]); return out; },
  async find(arr, fn) { const a = Array.from(arr || []); for (let i = 0; i < a.length; i++) if (await fn(a[i], i, a)) return a[i]; return undefined; },
  async findIndex(arr, fn) { const a = Array.from(arr || []); for (let i = 0; i < a.length; i++) if (await fn(a[i], i, a)) return i; return -1; },
  async some(arr, fn) { const a = Array.from(arr || []); for (let i = 0; i < a.length; i++) if (await fn(a[i], i, a)) return true; return false; },
  async every(arr, fn) { const a = Array.from(arr || []); for (let i = 0; i < a.length; i++) if (!(await fn(a[i], i, a))) return false; return true; },
  async flatMap(arr, fn) { return [].concat(...(await seq.map(arr, fn))); },
  async reduce(arr, fn, ...init) {
    const a = Array.from(arr || []); let i = 0; let acc;
    if (init.length) acc = init[0]; else { if (!a.length) throw new TypeError('Reduce of empty array with no initial value'); acc = a[0]; i = 1; }
    for (; i < a.length; i++) acc = await fn(acc, a[i], i, a);
    return acc;
  }
};

module.exports = {
  run, firebaseDbRequest_, firestoreGet_, firestoreSet_, firestoreUpdate_, firestoreAdd_, firestoreDelete_,
  firestoreQuery_, firestoreCount_, requireUser_, firebaseAuthRequest_, LockService, Utilities, seq
};
